    public static boolean committed(BotModeDecision d){return d!=null&&(d.directive().equals("mine")||d.objectivePriority()>=.9||List.of("ctf_","classic_ctf_","vip_","multihill_","territory_","demolition_","diamond_","occupation_","zombie_","arena_").stream().anyMatch(d.role()::startsWith));}
    public static boolean allowsCombat(BotModeDecision d,Player p,Player target,double now){if(d==null)return true;double gap=distance(p.position(),target.position());boolean hit=p.lastDamageSourceId()==target.id()&&p.lastDamageAt()>0&&now-p.lastDamageAt()<=2;if(hit||gap<=4.5)return true;double radius=Math.max(0,d.engagementRadius());return Set.of(DEFEND,ESCORT,BUILD,MINE).contains(d.posture())?gap<=Math.min(radius,14)||distance(d.position(),target.position())<=radius:gap<=radius;}
    static BotModeDecision watch(Perception f,Player p,BotModeDecision d){if(d==null||d.watchPosition()!=null||!Set.of(DEFEND,ESCORT,SURVIVE,EVASIVE,BUILD).contains(d.posture()))return d;var approach=enemy(f,"team_anchor",p);if(approach==null)approach=enemy(f,"vip",p);return approach==null?d:d(d.position(),d.role(),d.sprint(),d.arrivalRadius(),d.directive(),d.posture(),d.objectivePriority(),d.engagementRadius(),approach.position());}
    static boolean liveRole(String role){return ZOMBIE_ROLE_LIVE.contains(role)||List.of("escort","hunt","escape","evade","intercept","siege").stream().anyMatch(role::contains);}
    private record Commitment(List<Object> signature,BotModeDecision decision,double roleSince,double anchorSince,double lastSeen){}
    public record MemoryState(int id,int generation,BotModeDecision decision,double roleSince,double anchorSince,double lastSeen){}
    /** Role and route-anchor hysteresis with authoritative epoch/life signatures. */
    public static final class Memory {
        private final Thread owner=Thread.currentThread();private final BotModePolicies policies;private long map=-1,mode=-1;private final LinkedHashMap<Observer,Commitment> states=new LinkedHashMap<>();
        public Memory(BotModePolicies policies){this.policies=Objects.requireNonNull(policies);}
        void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Mode memory outside worker");}
        public void reset(){owned();states.clear();map=mode=-1;}public void forget(int id,int generation){owned();states.remove(new Observer(id,generation));}
        public List<MemoryState> snapshot(){owned();return states.entrySet().stream().map(e->new MemoryState(e.getKey().id(),e.getKey().generation(),e.getValue().decision(),e.getValue().roleSince(),e.getValue().anchorSince(),e.getValue().lastSeen())).toList();}
        public BotModeDecision decide(Perception f,Player p){owned();if(map!=f.mapEpoch()||mode!=f.modeEpoch()){reset();map=f.mapEpoch();mode=f.modeEpoch();}var key=new Observer(p.id(),p.generation());var decision=policies.objectiveDecision(f,p);if(decision==null)decision=standingOrder(f,p);if(!committed(decision)){states.remove(key);return decision;}double now=f.createdAt();var signature=new ArrayList<Object>();signature.addAll(Arrays.asList(canonical(f.mode()),f.modePhase(),p.lifeId(),p.team(),p.classId(),p.carriedEntityId(),decision.role().equals("vip_retreat")?p.lastDamageSourceId():-1));var objectives=new ArrayList<Object>();for(var o:f.objectives())if(!o.kind().equals("zombie_order")||o.carrierId()==p.id())objectives.add(Arrays.asList(o.kind(),o.team(),o.carrierId(),o.state(),o.carrierId()<0&&!o.kind().equals("vip")?o.position():null));signature.add(objectives);var previous=states.get(key);if(previous!=null&&(!previous.signature().equals(signature)||now<previous.lastSeen()))previous=null;if(previous!=null){var before=previous.decision();if(Set.of("vip","hc_vip").contains(canonical(f.mode()))&&Set.of("vip_guard_formation","vip_flank_attack","vip_mop_up").contains(before.role())&&Set.of("vip_guard_formation","vip_flank_attack","vip_mop_up").contains(decision.role())&&now-previous.roleSince()<8)decision=watch(f,p,vip(f,p,before.role()));boolean waited=before.role().endsWith("ctf_rally");if(waited!=decision.role().endsWith("ctf_rally")){double age=now-previous.roleSince();if(waited&&age<1.5&&!hurt(f,p,4)||!waited&&before.role().endsWith("ctf_attack_intel")&&age<3)decision=before;}
                if(decision.role().equals(before.role())){double separation=distance(decision.position(),before.position());boolean hold=separation<=3&&Math.abs(decision.position().z()-before.position().z())<=1;if(!liveRole(decision.role())&&now-previous.anchorSince()<8)hold|=distance(p.position(),decision.position())+6>=distance(p.position(),before.position());if(decision.role().equals("vip_retreat")&&now-previous.anchorSince()<4)hold=true;if(hold&&Set.of("vip_flank_attack","vip_sudden_death_assault","vip_lone_hunt").contains(decision.role())&&distance(p.position(),before.position())<=decision.arrivalRadius()+.5)hold=false;if(hold)decision=position(decision,before.position());}}
            double roleSince=previous!=null&&previous.decision().role().equals(decision.role())?previous.roleSince():now;double anchorSince=previous!=null&&previous.decision().position().equals(decision.position())?previous.anchorSince():now;if(!states.containsKey(key)&&states.size()>=64){var oldest=states.entrySet().stream().min(Comparator.comparingDouble(e->e.getValue().lastSeen())).orElseThrow().getKey();states.remove(oldest);}states.put(key,new Commitment(Collections.unmodifiableList(signature),decision,roleSince,anchorSince,now));return decision;
        }
    }
